    atoms.append((int(line[22:26]),el,[float(line[30:38]),float(line[38:46]),float(line[46:54])]))
ids=sorted({a[0] for a in atoms})
RADII={"C":1.70,"N":1.55,"O":1.52,"S":1.80}; PROBE=1.4
# Match PDBParser float32 coordinate storage, independently compute in float64.
xyz=np.asarray([a[2] for a in atoms],dtype=np.float32).astype(np.float64)
rad=np.array([RADII[a[1]]+PROBE for a in atoms])
d2=((xyz[:,None,:]-xyz[None,:,:])**2).sum(axis=2)
def baseline(n):
    sphere=np.empty((n,3),dtype=np.float32)
    z=1.0-1.0/n; angle=0.0; step=math.pi*(3-math.sqrt(5))
    for k in range(n):
        rr=math.sqrt(1-z*z)
        sphere[k]=(math.cos(angle)*rr,math.sin(angle)*rr,z)
        z-=2.0/n; angle+=step
    sphere=sphere.astype(np.float64)
